// Des: Unit tests for fire counters and next fire stamp
// Flo: arm tasks > set counters > ask by id > assert exact values
// I/O: armed tasks + Local > counts, kind, next minute stamp
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const supe = @import("tasksuper"); const tick = @import("tk-task-tick.zig");
const tszz = std.testing; const Sche = tick.Sche; const CF = tick.CF;
test "fireCoun reports the counter, last fire and type of the armed task with that id" { var sche: Sche = .{}; sche.gpaz = tszz.allocator; var arme = [_]armz.Armed{ try armz.armTask(.{ .id = "a", .type = "cron", .sche = "0 2 * * *", .run = "x" }), try armz.armTask(.{ .id = "b", .type = "hand", .run = "y" }) }; arme[0].fire_count = 3; arme[0].last_fire_ms = 1234; arme[1].fire_count = 9; sche.arme = &arme; const resa = sche.fireCoun("a").?; try tszz.expectEqual(@as(u32, 3), resa.coun); try tszz.expectEqual(@as(i64, 1234), resa.last_msec); try tszz.expectEqualStrings("cron", resa.kind); const resb = sche.fireCoun("b").?; try tszz.expectEqual(@as(u32, 9), resb.coun); try tszz.expectEqual(@as(i64, 0), resb.last_msec); }
test "fireCoun answers null for an unknown id, a near-miss id, and an empty arm list" { var sche: Sche = .{}; sche.gpaz = tszz.allocator; try tszz.expect(sche.fireCoun("a") == null); var arme = [_]armz.Armed{try armz.armTask(.{ .id = "ab", .type = "hand", .run = "x" })}; sche.arme = &arme; try tszz.expect(sche.fireCoun("a") == null); try tszz.expect(sche.fireCoun("abc") == null); try tszz.expect(sche.fireCoun("") == null); try tszz.expect(sche.fireCoun("ab") != null); }
test "fireNext gives the next 02:00 of a cron task, and null for a hand task or an unknown id" { var sche: Sche = .{}; sche.gpaz = tszz.allocator; var arme = [_]armz.Armed{ try armz.armTask(.{ .id = "c", .type = "cron", .sche = "0 2 * * *", .run = "x" }), try armz.armTask(.{ .id = "h", .type = "hand", .run = "y" }) }; sche.arme = &arme; const days = time.daysFromCivil(2026, 7, 14); const nowz: time.Local = .{ .year = 2026, .month = 7, .day = 14, .hour = 1, .minute = 0, .second = 0, .weekday = @intCast(@mod(days + 4, 7)), .minute_stamp = days * 1440 + 60 }; try tszz.expectEqual(@as(?i64, days * 1440 + 120), sche.fireNext("c", nowz)); const late: time.Local = .{ .year = 2026, .month = 7, .day = 14, .hour = 2, .minute = 0, .second = 0, .weekday = nowz.weekday, .minute_stamp = days * 1440 + 120 }; try tszz.expectEqual(@as(?i64, (days + 1) * 1440 + 120), sche.fireNext("c", late)); try tszz.expect(sche.fireNext("h", nowz) == null); try tszz.expect(sche.fireNext("nope", nowz) == null); }
